cases = [{}, {'files': {'data/deliveries.csv': 'order_id,area,minutes,price\nB01,,40,18000\nB02,south,33,26000\nB03,south,,9750\nB04,west,28,61000\nB05,south,36,20000\nB06,west,24,17000\nB07,,,23000\nB05,south,36,20000\nB08,east,30,16000\nB09,west,120,19000\n'}}, {'files': {'data/deliveries.csv': 'order_id,area,minutes,price\nC01,east,26,15000\nC02,east,,21000\nC03,north,31,18000\nC04,,19,800\nC05,west,44,24000\nC06,east,23,16000\nC07,north,,32000\nC06,east,23,16000\nC08,,22,20000\nC09,west,21,150000\nC10,east,150,19000\nC11,north,28,22000\nC08,,22,20000\nC12,west,33,17000\nC13,,,23000\n'}}]
